using ASMILE.BO.Core.FrontOffice.Foundation.Identifiers;

namespace ASMILE.BO.Core.FrontOffice.HotelMasterData;

public enum HotelComplaintSeverity { Low = 1, Medium = 2, High = 3, Critical = 4 }

public sealed class HotelComplaintProfile
{
    private HotelComplaintProfile() { }
    public Guid HotelComplaintProfileId { get; private set; } public Guid PropertyId { get; private set; } public string Code { get; private set; } = string.Empty; public string Name { get; private set; } = string.Empty; public string Category { get; private set; } = string.Empty; public HotelComplaintSeverity Severity { get; private set; } public string Department { get; private set; } = string.Empty; public int SlaMinutes { get; private set; } public int EscalationMinutes { get; private set; } public bool CompensationAllowed { get; private set; } public DateTime EffectiveFrom { get; private set; } public DateTime EffectiveTo { get; private set; } public string? Description { get; private set; } public bool IsActive { get; private set; } public DateTime CreatedAtUtc { get; private set; } public Guid? CreatedBy { get; private set; } public DateTime UpdatedAtUtc { get; private set; } public Guid? UpdatedBy { get; private set; } public byte[]? RowVersion { get; private set; }
    public static HotelComplaintProfile Create(PropertyId propertyId, string code, string name, string category, HotelComplaintSeverity severity, string department, int slaMinutes, int escalationMinutes, bool compensationAllowed, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, category, severity, department, slaMinutes, escalationMinutes, from, to); return new() { HotelComplaintProfileId = Uuid7.NewGuid(), PropertyId = propertyId.Value, Code = CodeValue(code), Name = name.Trim(), Category = category.Trim(), Severity = severity, Department = department.Trim(), SlaMinutes = slaMinutes, EscalationMinutes = escalationMinutes, CompensationAllowed = compensationAllowed, EffectiveFrom = from.Date, EffectiveTo = to.Date, Description = Normalize(description), IsActive = true, CreatedAtUtc = nowUtc, CreatedBy = actorId?.Value, UpdatedAtUtc = nowUtc, UpdatedBy = actorId?.Value }; }
    public void Update(string code, string name, string category, HotelComplaintSeverity severity, string department, int slaMinutes, int escalationMinutes, bool compensationAllowed, DateTime from, DateTime to, string? description, DateTime nowUtc, ActorId? actorId) { Validate(code, name, category, severity, department, slaMinutes, escalationMinutes, from, to); Code = CodeValue(code); Name = name.Trim(); Category = category.Trim(); Severity = severity; Department = department.Trim(); SlaMinutes = slaMinutes; EscalationMinutes = escalationMinutes; CompensationAllowed = compensationAllowed; EffectiveFrom = from.Date; EffectiveTo = to.Date; Description = Normalize(description); Touch(nowUtc, actorId); }
    public void Activate(DateTime nowUtc, ActorId? actorId) { IsActive = true; Touch(nowUtc, actorId); } public void Deactivate(DateTime nowUtc, ActorId? actorId) { IsActive = false; Touch(nowUtc, actorId); }
    private static void Validate(string code, string name, string category, HotelComplaintSeverity severity, string department, int sla, int escalation, DateTime from, DateTime to) { if (string.IsNullOrWhiteSpace(code)) throw new ArgumentException("HOTEL_COMPLAINT_CODE_REQUIRED"); if (string.IsNullOrWhiteSpace(name)) throw new ArgumentException("HOTEL_COMPLAINT_NAME_REQUIRED"); if (string.IsNullOrWhiteSpace(category)) throw new ArgumentException("HOTEL_COMPLAINT_CATEGORY_REQUIRED"); if (!Enum.IsDefined(severity)) throw new ArgumentException("HOTEL_COMPLAINT_SEVERITY_INVALID"); if (string.IsNullOrWhiteSpace(department)) throw new ArgumentException("HOTEL_COMPLAINT_DEPARTMENT_REQUIRED"); if (sla < 0 || escalation < 0) throw new ArgumentException("HOTEL_COMPLAINT_MINUTES_INVALID"); if (to.Date < from.Date) throw new ArgumentException("HOTEL_COMPLAINT_EFFECTIVE_RANGE_INVALID"); }
    private static string CodeValue(string value) => value.Trim().ToUpperInvariant(); private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim(); private void Touch(DateTime nowUtc, ActorId? actorId) { UpdatedAtUtc = nowUtc; UpdatedBy = actorId?.Value; }
}
